-- Tranche 12 delta (staged 2026-11-25, v2 publish tranche 12, Option D gate with Census pin first and town-center fallback): towns rows for the new towns the published listings sit in.
-- Centers are the centroid of the town's own Census-matched address pins
-- from this tranche, or of its sheet pins where the town carries only
-- fallback listings. listing_count counts only the listings this set
-- publishes in the town.
INSERT INTO towns (state, city_slug, city, state_slug, lat, lng, tz, listing_count) VALUES ('TX', 'crowley', 'Crowley', 'texas', 32.574078, -97.353284, NULL, 1) ON CONFLICT (state, city_slug) DO UPDATE SET city = excluded.city, state_slug = excluded.state_slug, lat = excluded.lat, lng = excluded.lng, tz = excluded.tz, listing_count = excluded.listing_count;
